import {
  corsHeaders,
  jsonResponse as sharedJsonResponse,
  requireCronOrUserAuth,
} from "../_shared/http.ts";
import {
  assertWebRouterUrlAllowed,
  resolveWebRouterApiUrl,
  validateWebRouterPayload,
} from "../_shared/webrouter.ts";

type RouteRequest = Record<string, unknown>;

function jsonResponse(body: unknown, status = 200) {
  return sharedJsonResponse(body, status);
}

function getApiUrl() {
  const configuredUrl = Deno.env.get("WEBROUTER_API")?.trim();
  if (!configuredUrl) {
    throw new Error("Secret WEBROUTER_API não configurado");
  }
  const resolved = resolveWebRouterApiUrl(configuredUrl);
  assertWebRouterUrlAllowed(resolved);
  return resolved;
}

function getProviderHeaders() {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json",
  };

  const authHeader = Deno.env.get("WEBROUTER_AUTH_HEADER")?.trim();
  const authToken = Deno.env.get("WEBROUTER_AUTH_TOKEN")?.trim();

  if (authHeader && authToken) {
    headers[authHeader] = authToken;
  }

  return headers;
}

function normalizeRouteResponse(data: Record<string, unknown>) {
  const rotas = data?.rotas;
  const route = Array.isArray(rotas) ? rotas[0] as Record<string, unknown> : null;
  const path = (route?.path ?? {}) as Record<string, unknown>;
  const tollsInfo = (route?.informacaoPedagios ?? {}) as Record<string, unknown>;
  const tolls = (tollsInfo.result ?? {}) as Record<string, unknown>;
  const summary = (route?.resumo ?? {}) as Record<string, unknown>;
  const costs = (route?.custos ?? {}) as Record<string, unknown>;

  const numberOrNull = (value: unknown) => {
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
  };

  return {
    status: data?.status ?? route?.status ?? null,
    distanciaKm: numberOrNull(path.distanciaKM),
    distanciaMetros: numberOrNull(path.distanciaMetros),
    distanciaRodoviariaKm: numberOrNull(path.distanciaRodoviariaKM),
    distanciaRodoviariaMetros: numberOrNull(path.distanciaRodoviariaMetros),
    distanciaUrbanaKm: numberOrNull(path.distanciaUrbanaKM),
    duracaoSegundos: numberOrNull(path.tempoSegundos),
    tempoFormatado: path.tempoFormatado ?? null,
    pedagios: Array.isArray(tolls.pedagios) ? tolls.pedagios : [],
    quantidadePedagios:
      numberOrNull(summary.quantidadePedagios) ??
      (Array.isArray(tolls.pedagios) ? tolls.pedagios.length : 0),
    valorPedagio:
      numberOrNull(costs.pedagio) ?? numberOrNull(tolls.totalPedagio),
    valorPedagioTag:
      numberOrNull(costs.pedagioTag) ?? numberOrNull(tolls.totalPedagioTag),
    rota: route,
  };
}

console.info("calculate-distance-webrouter started");

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Use o método POST." }, 405);
  }

  // SEC-EDGE-003: auth required; destination fixed by env allowlist (not client).
  const denied = await requireCronOrUserAuth(req);
  if (denied) return denied;

  try {
    const payload = (await req.json()) as RouteRequest;
    const validated = validateWebRouterPayload(payload);
    if (!validated.ok) {
      return jsonResponse({ error: validated.error }, 400);
    }

    const response = await fetch(getApiUrl(), {
      method: "POST",
      headers: getProviderHeaders(),
      body: JSON.stringify(validated.body),
      // SEC-EDGE-003: never follow redirects to a non-allowlisted host
      redirect: "error",
    });

    const rawText = await response.text();
    let providerData: unknown;

    try {
      providerData = rawText ? JSON.parse(rawText) : {};
    } catch {
      return jsonResponse(
        {
          error: "O WebRouter retornou uma resposta que não é JSON.",
          providerStatus: response.status,
          providerResponse: rawText.slice(0, 2000),
        },
        502,
      );
    }

    const normalized = normalizeRouteResponse(
      (providerData && typeof providerData === "object"
        ? providerData
        : {}) as Record<string, unknown>,
    );

    if (!response.ok) {
      return jsonResponse(
        {
          error: "O WebRouter recusou a consulta.",
          providerStatus: response.status,
          ...normalized,
          providerResponse: providerData,
        },
        502,
      );
    }

    if (normalized.status && normalized.status !== "SUCESSO") {
      return jsonResponse(
        {
          error: "O WebRouter não conseguiu calcular a rota.",
          ...normalized,
          providerResponse: providerData,
        },
        422,
      );
    }

    return jsonResponse({
      success: true,
      ...normalized,
      providerResponse: providerData,
    });
  } catch (error) {
    return jsonResponse(
      {
        error: error instanceof Error
          ? error.message
          : "Erro interno ao calcular a rota.",
      },
      500,
    );
  }
});

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, idempotency-key",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, OPTIONS",
};

export type AuthDecision =
  | "CRON_AUTHENTICATED"
  | "USER_AUTHENTICATED"
  | "REJECTED";

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      "Content-Type": "application/json; charset=utf-8",
    },
  });
}

export function errorDetail(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (error && typeof error === "object") {
    const record = error as Record<string, unknown>;
    const parts = [record.message, record.details, record.hint, record.code]
      .filter((part) => typeof part === "string" && part.length > 0);
    if (parts.length > 0) return parts.join(" | ");
    try {
      return JSON.stringify(error);
    } catch {
      return String(error);
    }
  }
  return String(error);
}

/** Extract Bearer token; empty/malformed → null. Does NOT authenticate. */
export function extractBearerToken(req: Request): string | null {
  const auth = req.headers.get("Authorization");
  if (auth == null) return null;
  const trimmed = auth.trim();
  if (!trimmed.toLowerCase().startsWith("bearer ")) return null;
  const token = trimmed.slice("bearer ".length).trim();
  return token.length > 0 ? token : null;
}

/**
 * Cron auth: exact match of Bearer token to SYNC_CRON_SECRET.
 * Fail-closed if secret missing/empty. Presence of "Bearer " is never enough.
 */
export function authenticateCron(req: Request): AuthDecision {
  const secret = Deno.env.get("SYNC_CRON_SECRET")?.trim();
  if (!secret) return "REJECTED";
  const token = extractBearerToken(req);
  if (!token) return "REJECTED";
  return token === secret ? "CRON_AUTHENTICATED" : "REJECTED";
}

/** @deprecated Prefer authenticateCron; kept for sync-* call sites. */
export function validateCronAuth(req: Request): boolean {
  return authenticateCron(req) === "CRON_AUTHENTICATED";
}

/**
 * Require cron secret for privileged sync triggers.
 * Returns 401 Response on failure; null when CRON_AUTHENTICATED.
 */
export function requireCronAuth(req: Request): Response | null {
  if (authenticateCron(req) === "CRON_AUTHENTICATED") return null;
  return jsonResponse({ error: "Unauthorized" }, 401);
}

/**
 * Validate Supabase Auth JWT (user session). Fail-closed on missing env/token/user.
 * Does not treat cron secret as a user session.
 */
export async function authenticateUserJwt(req: Request): Promise<AuthDecision> {
  const token = extractBearerToken(req);
  if (!token) return "REJECTED";

  const cronSecret = Deno.env.get("SYNC_CRON_SECRET")?.trim();
  if (cronSecret && token === cronSecret) {
    // Cron is not a user identity for signed-URL / user-scoped routes.
    return "REJECTED";
  }

  const url = Deno.env.get("SUPABASE_URL")?.trim();
  const anon = Deno.env.get("SUPABASE_ANON_KEY")?.trim();
  if (!url || !anon) return "REJECTED";

  try {
    const { createClient } = await import("npm:@supabase/supabase-js@2");
    const client = createClient(url, anon, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
    const { data, error } = await client.auth.getUser(token);
    if (error || !data.user) return "REJECTED";
    return "USER_AUTHENTICATED";
  } catch {
    return "REJECTED";
  }
}

export async function requireUserAuth(req: Request): Promise<Response | null> {
  if ((await authenticateUserJwt(req)) === "USER_AUTHENTICATED") return null;
  return jsonResponse({ error: "Unauthorized" }, 401);
}

/**
 * Cron OR authenticated user (for ops that allow either).
 * Still fail-closed; never accepts arbitrary Bearer strings.
 */
export async function authenticateCronOrUser(req: Request): Promise<AuthDecision> {
  const cron = authenticateCron(req);
  if (cron === "CRON_AUTHENTICATED") return cron;
  return await authenticateUserJwt(req);
}

export async function requireCronOrUserAuth(req: Request): Promise<Response | null> {
  const decision = await authenticateCronOrUser(req);
  if (decision === "CRON_AUTHENTICATED" || decision === "USER_AUTHENTICATED") {
    return null;
  }
  return jsonResponse({ error: "Unauthorized" }, 401);
}

export function parseQueryInt(
  url: URL,
  key: string,
  fallback: number,
): number {
  const raw = url.searchParams.get(key);
  if (!raw) return fallback;
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) ? n : fallback;
}

/** Allowed WebRouter hosts — destination never comes from the client. */
export const WEBROUTER_ALLOWED_HOSTS = new Set([
  "way.webrouter.com.br",
  "way-hml.webrouter.com.br",
]);

/** Keys that must never appear in client payload (proxy/SSRF hints). */
export const WEBROUTER_FORBIDDEN_PAYLOAD_KEYS = new Set([
  "url",
  "uri",
  "host",
  "hostname",
  "endpoint",
  "proxy",
  "target",
  "baseUrl",
  "base_url",
  "webhook",
  "callback",
  "redirect",
]);

export function resolveWebRouterApiUrl(configuredUrl: string): string {
  const trimmed = configuredUrl.trim();
  if (!trimmed) {
    throw new Error("Secret WEBROUTER_API não configurado");
  }
  if (/\/router\/api\/calcular\/?$/i.test(trimmed)) {
    return trimmed.replace(/\/+$/, "");
  }
  return `${trimmed.replace(/\/+$/, "")}/router/api/calcular`;
}

export function assertWebRouterUrlAllowed(apiUrl: string): void {
  let parsed: URL;
  try {
    parsed = new URL(apiUrl);
  } catch {
    throw new Error("WEBROUTER_API inválido");
  }
  if (parsed.protocol !== "https:") {
    throw new Error("WEBROUTER_API deve usar https");
  }
  if (!WEBROUTER_ALLOWED_HOSTS.has(parsed.hostname.toLowerCase())) {
    throw new Error("WEBROUTER_API host fora da allowlist");
  }
  if (!/\/router\/api\/calcular\/?$/i.test(parsed.pathname)) {
    throw new Error("WEBROUTER_API path deve terminar em /router/api/calcular");
  }
}

export function validateWebRouterPayload(
  payload: unknown,
): { ok: true; body: Record<string, unknown> } | { ok: false; error: string } {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return { ok: false, error: "O corpo da requisição deve ser um JSON de objeto." };
  }
  const body = payload as Record<string, unknown>;
  for (const key of Object.keys(body)) {
    if (WEBROUTER_FORBIDDEN_PAYLOAD_KEYS.has(key)) {
      return { ok: false, error: "Payload contém campos não permitidos." };
    }
  }
  const serialized = JSON.stringify(body);
  if (serialized.length > 32_768) {
    return { ok: false, error: "Payload excede o tamanho máximo permitido." };
  }
  return { ok: true, body };
}
